@cache
def extra_glyphs() -> dict[str, str]:
    table: dict[str, str] = {}
    for line in _ENTRIES.splitlines():
        name, *points = line.split(" ")
        table[name] = "".join(chr(int(point, 16)) for point in points)
    return table
